using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class CheckModelFolders {public static string Main(){string r=Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/ModelFolderCleanup_20261103"));AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(var p in new[]{"Assets/Afrer_Seconds/03.Art/Candidates/VARCO","Assets/Afrer_Seconds/03.Art/Candidates"})if(Directory.Exists(p)&&!Directory.EnumerateFileSystemEntries(p).Any())AssetDatabase.DeleteAsset(p);var plan=JArray.Parse(File.ReadAllText(r+"/move_plan.json"));var bad=plan.Where(a=>AssetDatabase.GUIDToAssetPath((string)a["guid"])!=(string)a["destination"]).ToArray();if(bad.Length>0)throw new Exception("GUID mismatch");var deps=JObject.Parse(File.ReadAllText(r+"/scene_dependency_guids_before.json"));int scenes=0;foreach(var x in deps.Properties()){var now=AssetDatabase.GetDependencies(x.Name,true).Select(AssetDatabase.AssetPathToGUID).Where(g=>!string.IsNullOrEmpty(g)).Distinct().OrderBy(g=>g);if(!now.SequenceEqual(((JArray)x.Value).Select(v=>(string)v)))throw new Exception("Scene refs changed "+x.Name);scenes++;}int beforeMats=plan.Count(a=>Path.GetExtension((string)a["path"])==".mat");int afterMats=AssetDatabase.GetAllAssetPaths().Count(p=>p.StartsWith("Assets/Afrer_Seconds/05.Model/")&&Path.GetExtension(p)==".mat");if(beforeMats!=afterMats)throw new Exception("Material count changed");var active=SceneManager.GetActiveScene();var all=active.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();int missing=all.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));int missingMeshes=all.SelectMany(t=>t.GetComponents<MeshFilter>()).Count(f=>!f.sharedMesh);int missingMaterials=all.SelectMany(t=>t.GetComponents<Renderer>()).Sum(rr=>rr.sharedMaterials.Count(m=>!m));if(missing+missingMeshes+missingMaterials>0)throw new Exception("Missing scene refs");var result=new{guidsPreserved=plan.Count,sceneDependencyChecks=scenes,materialsBefore=beforeMats,materialsAfter=afterMats,newMaterials=0,activeScene=active.path,activeSceneDirty=active.isDirty,missingScripts=missing,missingMeshes,missingMaterials};File.WriteAllText(r+"/final_verification.json",JsonConvert.SerializeObject(result,Formatting.Indented));return JsonConvert.SerializeObject(result);}}
